content.content:
1	/* Cyrus studios mockup: shared kit. Tokens copied from app/dashboard/cyrus/studio.css (v5, the owner's handoff)
2	   and cyrus.css (--cy-* ok/warn/alert). One accent (violet); cyan only for "live" (playhead, live pixel, focus of
3	   the current candidate); semantic ok/warn/bad for checks. */
4	@font-face { font-family: "Inter"; src: url(../assets/fonts/inter-400.woff2) format("woff2"); font-weight: 400 500; }
5	@font-face { font-family: "Inter"; src: url(../assets/fonts/inter-600.woff2) format("woff2"); font-weight: 600 700; }
6	@font-face { font-family: "JetBrains Mono"; src: url(../assets/fonts/jb-400.woff2) format("woff2"); font-weight: 400; }
7	@font-face { font-family: "JetBrains Mono"; src: url(../assets/fonts/jb-500.woff2) format("woff2"); font-weight: 500 700; }
8	@font-face { font-family: "Space Grotesk"; src: url(../assets/fonts/sg-500.woff2) format("woff2"); font-weight: 500; }
9	@font-face { font-family: "Space Grotesk"; src: url(../assets/fonts/sg-600.woff2) format("woff2"); font-weight: 600 700; }
10	
11	:root {
12	  color-scheme: dark;
13	  --bg: #05030b; --bg-2: #0a0617; --bg-3: #140b2b;
14	  --surface: rgb(15 10 32 / 0.6); --surface-2: rgb(22 15 46 / 0.78); --surface-3: rgb(40 27 80 / 0.55);
15	  --surface-soft: rgb(16 11 34 / 0.82); --solid: #0e091e; --well: rgb(7 4 18 / 0.55);
16	  --line: rgb(167 139 250 / 0.13); --line-2: rgb(167 139 250 / 0.26); --line-3: rgb(167 139 250 / 0.4);
17	  --ink: #f2eeff; --ink-2: #cfc7f0; --muted: #958cc0; --faint: #5f5789;
18	  --accent: #a78bfa; --accent-ink: #c4b5fd; --accent-solid: #7c4dff; --on-accent: #fff;
19	  --accent-soft: rgb(167 139 250 / 0.14); --accent-line: rgb(167 139 250 / 0.5);
20	  --cyan: #67e8f9; --glow: 167 139 250;
21	  --ok: #34e3a2; --warn: #ffb44f; --bad: #ff6b8a; --ok-soft: rgb(52 227 162 / .1); --warn-soft: rgb(255 180 79 / .1); --bad-soft: rgb(255 90 130 / .1);
22	  --panel-shadow: 0 30px 80px -24px rgb(0 0 0 / 0.8), inset 0 1px 0 rgb(255 255 255 / 0.04);
23	  --pop-shadow: 0 26px 70px -20px rgb(0 0 0 / .9), 0 0 0 1px rgb(150 160 255 / .14);
24	  --check-a: #2b2545; --check-b: #221d3a;
25	  --sans: "Inter", ui-sans-serif, system-ui, sans-serif; --mono: "JetBrains Mono", ui-monospace, monospace; --display: "Space Grotesk", "Inter", sans-serif;
26	  --ease: cubic-bezier(0.16, 1, 0.3, 1);
27	  --r-sm: 7px; --r: 10px; --r-md: 12px; --r-lg: 16px; --r-xl: 20px;
28	}
29	:root[data-theme="light"] {
30	  color-scheme: light;
31	  --bg: #fdfcff; --bg-2: #f7f4ff; --bg-3: #ede7ff;
32	  --surface: rgb(255 255 255 / 0.7); --surface-2: rgb(255 255 255 / 0.92); --surface-3: rgb(243 238 255 / 0.9);
33	  --surface-soft: rgb(255 255 255 / 0.9); --solid: #fff; --well: #f6f3fd;
34	  --line: rgb(91 33 182 / 0.1); --line-2: rgb(91 33 182 / 0.2); --line-3: rgb(91 33 182 / 0.32);
35	  --ink: #160f2c; --ink-2: #3a3162; --muted: #6b6390; --faint: #a8a1c6;
36	  --accent: #7c3aed; --accent-ink: #6d28d9; --accent-solid: #7c3aed; --accent-soft: rgb(109 61 240 / .09); --accent-line: rgb(109 61 240 / .4);
37	  --cyan: #0891b2; --glow: 124 58 237;
38	  --ok: #047a52; --warn: #8a4b00; --bad: #c8204f; --ok-soft: rgb(4 122 82 / .08); --warn-soft: rgb(196 110 0 / .08); --bad-soft: rgb(200 32 79 / .07);
39	  --panel-shadow: 0 24px 60px -28px rgb(76 29 149 / 0.28), inset 0 1px 0 rgb(255 255 255 / 0.9);
40	  --pop-shadow: 0 24px 60px -20px rgb(20 22 60 / .3), 0 0 0 1px rgb(30 36 90 / .1);
41	  --check-a: #ece8f6; --check-b: #f8f6fd;
42	}
43	* { box-sizing: border-box; }
44	html, body { margin: 0; height: 100%; }
45	body { background: var(--bg); color: var(--ink); font: 400 13px/1.45 var(--sans); -webkit-font-smoothing: antialiased; font-feature-settings: "ss01", "cv11"; overflow: hidden; }
46	button, input, select, textarea { font: inherit; color: inherit; }
47	button { cursor: pointer; background: none; border: 0; padding: 0; text-align: inherit; }
48	a { color: inherit; text-decoration: none; }
49	:focus-visible { outline: 2px solid var(--accent-ink); outline-offset: 2px; border-radius: 6px; }
50	::selection { background: rgb(var(--glow) / .35); }
51	* { scrollbar-width: thin; scrollbar-color: rgb(var(--glow) / .28) transparent; }
52	.mono { font-family: var(--mono); }
53	.sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }
54	svg.i { width: 1em; height: 1em; flex: none; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
55	
56	/* ── app frame: portal rail (dark island in both themes, like the real sidebar) + the Cyrus surface ── */
57	.app { display: grid; grid-template-columns: 60px 1fr; height: 100vh; }
58	.nxrail { background: #070b1a; border-right: 1px solid rgb(120 140 255 / .12); display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 14px 0; }
59	.nxrail .nx { width: 30px; height: 30px; margin-bottom: 14px; object-fit: contain; }
60	.nxrail a { display: grid; place-items: center; width: 38px; height: 38px; border-radius: 10px; color: #7f8bb8; font-size: 18px; }
61	.nxrail a.on { color: #fff; background: linear-gradient(100deg, rgb(139 61 255 / .32), rgb(110 70 255 / .12)); box-shadow: inset 0 0 0 1px rgb(160 120 255 / .35); }
62	.nxrail .sp { flex: 1; }
63	.cyrus { position: relative; overflow: hidden; isolation: isolate; display: flex; flex-direction: column; min-width: 0; }
64	/* deep space: a faint aurora curtain + sparse stars; never ovals, never loud */
65	.cyrus::before { content: ""; position: absolute; inset: 0; z-index: -1; pointer-events: none;
66	  background:
67	    radial-gradient(1px 1px at 12% 18%, rgb(255 255 255 / .55), transparent 60%), radial-gradient(1px 1px at 78% 12%, rgb(255 255 255 / .4), transparent 60%),
68	    radial-gradient(1px 1px at 64% 72%, rgb(255 255 255 / .35), transparent 60%), radial-gradient(1px 1px at 28% 84%, rgb(255 255 255 / .3), transparent 60%),
69	    radial-gradient(1px 1px at 91% 58%, rgb(255 255 255 / .35), transparent 60%), radial-gradient(1px 1px at 44% 30%, rgb(255 255 255 / .25), transparent 60%),
70	    linear-gradient(118deg, transparent 8%, rgb(40 200 170 / .07) 18%, transparent 28%, transparent 62%, rgb(124 77 255 / .07) 74%, transparent 86%),
71	    radial-gradient(120% 70% at 50% -10%, rgb(60 30 130 / .35), transparent 60%), var(--bg); }
72	:root[data-theme="light"] .cyrus::before { background: linear-gradient(118deg, transparent 8%, rgb(8 145 178 / .05) 18%, transparent 30%, transparent 60%, rgb(124 58 237 / .06) 74%, transparent 88%), radial-gradient(120% 70% at 50% -10%, rgb(124 58 237 / .07), transparent 60%), var(--bg); }
73	
74	/* ── surfaces ── */
75	.glass { background: linear-gradient(180deg, var(--surface-2), var(--surface)); backdrop-filter: blur(14px) saturate(140%); -webkit-backdrop-filter: blur(14px) saturate(140%); border: 1px solid var(--line); box-shadow: var(--panel-shadow); }
76	.glass-soft { background: var(--surface-soft); border: 1px solid var(--line); }
77	.hairline { position: relative; }
78	.hairline::before { content: ""; position: absolute; inset: 0 12% auto 12%; height: 1px; pointer-events: none; background: linear-gradient(90deg, transparent, rgb(var(--glow) / .55), rgb(103 232 249 / .4), transparent); }
79	:root[data-theme="light"] .hairline::before { background: linear-gradient(90deg, transparent, rgb(124 58 237 / .3), rgb(8 145 178 / .25), transparent); }
80	.panel { border-radius: var(--r-lg); min-height: 0; display: flex; flex-direction: column; }
81	.ph { display: flex; align-items: center; gap: 8px; padding: 12px 14px 8px; }
82	.eyebrow { font: 600 10px/1 var(--mono); letter-spacing: .2em; text-transform: uppercase; color: var(--muted); }
83	.ph .eyebrow { flex: 1; }
84	.sep { height: 1px; background: var(--line); margin: 4px 0; }
85	
86	/* ── top bar (TopBar.tsx anatomy) ── */
87	.topbar { height: 60px; flex: none; display: flex; align-items: center; gap: 12px; padding: 0 16px 0 18px; position: relative; z-index: 5; }
88	.brand { display: flex; flex-direction: column; line-height: 1; }
89	.brand img { height: 19px; width: auto; display: block; filter: drop-shadow(0 0 8px rgb(139 92 246 / .45)); }
90	:root[data-theme="light"] .brand img { filter: none; }
91	.brand small { margin-top: 4px; font: 600 8px/1 var(--sans); letter-spacing: .36em; text-transform: uppercase; color: var(--muted); }
92	.wm-l { display: none !important; } :root[data-theme="light"] .wm-l { display: block !important; } :root[data-theme="light"] .wm-d { display: none !important; }
93	.crumbs { display: flex; align-items: center; gap: 2px; padding: 4px; border-radius: 12px; margin-left: 10px; min-width: 0; }
94	.crumb { display: flex; align-items: center; gap: 6px; padding: 4px 8px; border-radius: 8px; font-size: 12.5px; color: var(--muted); white-space: nowrap; }
95	.crumb:hover { color: var(--ink); background: rgb(var(--glow) / .07); }
96	.crumb.on { color: var(--ink); font-weight: 500; background: rgb(var(--glow) / .12); }
97	.crumb .core { width: 10px; height: 10px; border-radius: 50%; background: radial-gradient(circle at 35% 30%, #fff, var(--accent) 55%, var(--cyan)); box-shadow: 0 0 8px var(--accent); }
98	.crumb img { width: 15px; height: 15px; }
99	.crumbs > svg { font-size: 11px; color: var(--faint); }
100	.tb-r { margin-left: auto; display: flex; align-items: center; gap: 6px; }
101	.chip { display: inline-flex; align-items: center; gap: 7px; height: 36px; padding: 0 12px; border-radius: 12px; font-size: 12.5px; font-weight: 500; color: var(--ink-2); white-space: nowrap; }
102	.chip:hover { color: var(--ink); border-color: var(--line-2); }
103	.chip.icon { width: 36px; padding: 0; justify-content: center; font-size: 16px; }
104	.chip .coin { width: 18px; height: 18px; }
105	.chip b { font-weight: 600; color: var(--ink); font-family: var(--mono); font-size: 12px; }
106	.seg { display: inline-flex; padding: 3px; gap: 2px; border-radius: 12px; }
107	.seg button { height: 28px; padding: 0 11px; border-radius: 9px; font-size: 12.5px; font-weight: 500; color: var(--muted); display: inline-flex; align-items: center; gap: 6px; white-space: nowrap; }
108	.seg button:hover { color: var(--ink); }
109	.seg button.on { color: var(--ink); background: rgb(var(--glow) / .16); box-shadow: inset 0 0 0 1px rgb(var(--glow) / .28); }
110	.seg.sm button { height: 24px; padding: 0 8px; font-size: 11.5px; border-radius: 7px; }
111	.kbd { font: 500 10px/1 var(--mono); padding: 3px 5px; border-radius: 5px; border: 1px solid var(--line-2); color: var(--muted); background: rgb(var(--glow) / .06); }
112	
113	/* ── buttons / fields ── */
114	.btn { display: inline-flex; align-items: center; justify-content: center; gap: 7px; height: 32px; padding: 0 12px; border-radius: var(--r); font-size: 12.5px; font-weight: 500; color: var(--ink); border: 1px solid var(--line-2); background: var(--surface-2); white-space: nowrap; transition: background .15s, border-color .15s, transform .15s var(--ease); }
115	.btn:hover { background: rgb(var(--glow) / .14); border-color: var(--line-3); }
116	.btn.primary { color: var(--on-accent); border-color: transparent; background: var(--accent-solid); box-shadow: inset 0 1px 0 rgb(255 255 255 / .18), 0 8px 22px -12px rgb(124 77 255 / .9); }
117	.btn.primary:hover { filter: brightness(1.08); }
118	.btn.ghost { background: transparent; border-color: transparent; color: var(--ink-2); }
119	.btn.ghost:hover { background: rgb(var(--glow) / .1); color: var(--ink); }
120	.btn.sm { height: 28px; padding: 0 10px; font-size: 12px; border-radius: 8px; }
121	.btn.xs { height: 24px; padding: 0 8px; font-size: 11.5px; border-radius: 7px; gap: 5px; }
122	.btn.danger { color: var(--bad); }
123	.btn:disabled { opacity: .45; cursor: not-allowed; }
124	.ib { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 9px; color: var(--muted); font-size: 16px; transition: color .15s, background .15s; }
125	.ib:hover { color: var(--ink); background: rgb(var(--glow) / .1); }
126	.ib.on { color: var(--accent-ink); background: var(--accent-soft); }
127	.ib.sm { width: 24px; height: 24px; font-size: 14px; border-radius: 7px; }
128	.field { height: 32px; width: 100%; border-radius: var(--r); border: 1px solid var(--line-2); background: var(--well); padding: 0 10px; font-size: 12.5px; color: var(--ink); outline: none; }
129	.field:focus { border-color: var(--accent-line); box-shadow: 0 0 0 3px rgb(var(--glow) / .15); }
130	.field::placeholder { color: var(--faint); }
131	.field.err { border-color: color-mix(in srgb, var(--bad) 60%, transparent); box-shadow: 0 0 0 3px var(--bad-soft); }
132	label.lbl { display: block; font-size: 11.5px; font-weight: 500; color: var(--ink-2); margin-bottom: 5px; }
133	label.lbl .req { color: var(--bad); font-weight: 600; margin-left: 2px; }
134	.hint { font-size: 11.5px; color: var(--muted); line-height: 1.45; }
135	.hint.err { color: var(--bad); }
136	input[type=range] { -webkit-appearance: none; appearance: none; width: 100%; height: 18px; background: transparent; }
137	input[type=range]::-webkit-slider-runnable-track { height: 4px; border-radius: 4px; background: linear-gradient(90deg, var(--accent) var(--p, 50%), var(--line-2) var(--p, 50%)); }
138	input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; width: 12px; height: 12px; margin-top: -4px; border-radius: 50%; background: var(--solid); border: 2px solid var(--accent); box-shadow: 0 0 0 3px rgb(var(--glow) / .15); }
139	
140	/* ── tags / pills / status ── */
141	.tag { display: inline-flex; align-items: center; gap: 5px; font: 500 9.5px/1 var(--mono); letter-spacing: .08em; text-transform: uppercase; padding: 4px 6px; border-radius: 5px; color: var(--ink-2); border: 1px solid var(--line-2); white-space: nowrap; }
142	.tag.acc { color: var(--accent-ink); border-color: var(--accent-line); background: var(--accent-soft); }
143	.tag.ok { color: var(--ok); border-color: color-mix(in srgb, var(--ok) 40%, transparent); background: var(--ok-soft); }
144	.tag.warn { color: var(--warn); border-color: color-mix(in srgb, var(--warn) 40%, transparent); background: var(--warn-soft); }
145	.tag.bad { color: var(--bad); border-color: color-mix(in srgb, var(--bad) 40%, transparent); background: var(--bad-soft); }
146	.tag.dim { color: var(--muted); }
147	.dot { width: 7px; height: 7px; border-radius: 50%; flex: none; background: var(--faint); }
148	.dot.ok { background: var(--ok); } .dot.warn { background: var(--warn); } .dot.bad { background: var(--bad); } .dot.live { background: var(--cyan); box-shadow: 0 0 8px var(--cyan); }
149	.chiprow { display: flex; flex-wrap: wrap; gap: 6px; }
150	.fchip { white-space: nowrap; flex: none; height: 26px; padding: 0 10px; border-radius: 999px; border: 1px solid var(--line-2); font-size: 11.5px; color: var(--ink-2); display: inline-flex; align-items: center; gap: 6px; }
151	.fchip:hover { border-color: var(--line-3); color: var(--ink); }
152	.fchip.on { color: var(--accent-ink); border-color: var(--accent-line); background: var(--accent-soft); }
153	.fchip i { font-style: normal; font: 500 10px/1 var(--mono); color: var(--muted); }
154	
155	/* ── tabs (inspector anatomy: icon + label + mono count, underline) ── */
156	.tabs { display: flex; gap: 2px; padding: 0 10px; border-bottom: 1px solid var(--line); }
157	.tab { position: relative; display: inline-flex; align-items: center; gap: 6px; height: 40px; padding: 0 9px; font-size: 12.5px; font-weight: 500; color: var(--muted); }
158	.tab:hover { color: var(--ink); }
159	.tab.on { color: var(--ink); }
160	.tab.on::after { content: ""; position: absolute; left: 8px; right: 8px; bottom: -1px; height: 2px; border-radius: 2px; background: var(--accent); box-shadow: 0 0 10px rgb(var(--glow) / .7); }
161	.tab .n { font: 500 10px/1 var(--mono); padding: 2px 5px; border-radius: 5px; background: rgb(var(--glow) / .1); color: var(--muted); }
162	.tabpane { display: none; min-height: 0; overflow: auto; }
163	.tabpane.on { display: block; }
164	
165	/* ── lists ── */
166	.row { display: flex; align-items: center; gap: 10px; padding: 7px 10px; border-radius: var(--r); color: var(--ink-2); font-size: 12.5px; }
167	.row:hover { background: rgb(var(--glow) / .07); color: var(--ink); }
168	.row.on { background: rgb(var(--glow) / .13); color: var(--ink); box-shadow: inset 0 0 0 1px rgb(var(--glow) / .22); }
169	.row .grow { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
170	.row .meta { font: 500 10.5px/1 var(--mono); color: var(--muted); white-space: nowrap; }
171	.thumb { flex: none; width: 30px; height: 30px; border-radius: 8px; display: grid; place-items: center; background: repeating-conic-gradient(var(--check-a) 0 25%, var(--check-b) 0 50%) 0 0 / 8px 8px; border: 1px solid var(--line); overflow: hidden; }
172	.thumb canvas { width: 24px; height: 24px; image-rendering: pixelated; }
173	
174	/* ── check list (quality) ── */
175	.verdict { display: flex; align-items: center; gap: 10px; padding: 10px 12px; margin: 10px 12px 6px; border-radius: var(--r-md); border: 1px solid var(--line-2); background: rgb(var(--glow) / .05); }
176	.verdict b { font: 600 14px/1.1 var(--display); }
177	.verdict .hint { margin-top: 2px; }
178	.verdict .badge { margin-left: auto; }
179	.checks { list-style: none; margin: 0; padding: 4px 12px 12px; display: flex; flex-direction: column; gap: 2px; }
180	.check { display: grid; grid-template-columns: 18px 1fr auto; gap: 2px 10px; padding: 9px 4px; border-bottom: 1px solid var(--line); }
181	.check:last-child { border-bottom: 0; }
182	.check .ic { width: 18px; height: 18px; border-radius: 50%; display: grid; place-items: center; font-size: 11px; margin-top: 1px; }
183	.check.pass .ic { color: var(--ok); background: var(--ok-soft); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--ok) 40%, transparent); }
184	.check.warn .ic { color: var(--warn); background: var(--warn-soft); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--warn) 40%, transparent); }
185	.check.fail .ic { color: var(--bad); background: var(--bad-soft); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--bad) 40%, transparent); }
186	.check.not_run .ic { color: var(--faint); box-shadow: inset 0 0 0 1px var(--line-2); }
187	.check .id { font: 500 12px/1.3 var(--mono); color: var(--ink); }
188	.check .val { font: 500 11.5px/1.3 var(--mono); color: var(--ink-2); text-align: right; }
189	.check .msg { grid-column: 2 / 4; font-size: 11.5px; color: var(--muted); line-height: 1.4; }
190	.check .lim { grid-column: 2 / 4; font: 400 10.5px/1.3 var(--mono); color: var(--faint); }
191	
192	/* ── prompt dock (PromptDock anatomy, conic rim while active) ── */
193	@property --ang { syntax: "<angle>"; initial-value: 0deg; inherits: false; }
194	.dock { position: relative; border-radius: 20px; padding: 10px 10px 10px 14px; display: flex; align-items: center; gap: 10px; }
195	.dock::before { content: ""; position: absolute; inset: 0; border-radius: inherit; padding: 1px; pointer-events: none; z-index: 2;
196	  background: conic-gradient(from var(--ang), rgb(var(--glow) / .18) 0%, rgb(103 232 249 / .7) 12%, rgb(var(--glow) / .18) 26%, rgb(var(--glow) / .18) 48%, rgb(240 171 252 / .6) 62%, rgb(var(--glow) / .18) 76%);
197	  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0); -webkit-mask-composite: xor; mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0); mask-composite: exclude; }
198	.dock[data-active="true"]::before, .dock[data-busy="true"]::before { animation: spin 6s linear infinite; }
199	.dock[data-busy="true"]::before { animation-duration: 1.3s; }
200	@keyframes spin { to { --ang: 360deg; } }
201	.dock .route { display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 9px; border-radius: 8px; font-size: 12px; font-weight: 500; color: var(--accent-ink); background: var(--accent-soft); white-space: nowrap; }
202	.dock input { flex: 1; min-width: 0; height: 34px; border: 0; outline: none; background: transparent; font-size: 13.5px; color: var(--ink); }
203	.dock input::placeholder { color: var(--faint); }
204	.dock .model { display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 10px; border-radius: 9px; font-size: 12.5px; font-weight: 600; border: 1px solid var(--line); color: var(--ink); }
205	.dock .send { width: 36px; height: 36px; border-radius: 11px; display: grid; place-items: center; color: #fff; background: var(--accent-solid); font-size: 16px; box-shadow: inset 0 1px 0 rgb(255 255 255 / .2); }
206	.dock .est { font: 500 11px/1 var(--mono); color: var(--muted); white-space: nowrap; }
207	
208	/* ── candidate card (AI edit, non-destructive) ── */
209	.cand { margin: 10px 12px; border-radius: var(--r-md); border: 1px dashed var(--accent-line); background: linear-gradient(180deg, rgb(var(--glow) / .07), transparent 70%); }
