#!/usr/bin/env python3
"""Inline src/*.html + css + js + fonts + images into self-contained mockups in the design folder root."""
import base64, re, os
D = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); S = os.path.join(D, "src")
OUT = {"texture.html": "texture-studio.html", "sound.html": "sound-studio.html", "mod-assets.html": "mod-assets.html", "locked.html": "locked-states.html"}
MIME = {".webp": "image/webp", ".png": "image/png", ".svg": "image/svg+xml", ".woff2": "font/woff2"}
cache = {}
def data(rel):
    p = os.path.normpath(os.path.join(S, rel))
    if p not in cache: cache[p] = f"data:{MIME[os.path.splitext(p)[1]]};base64," + base64.b64encode(open(p, "rb").read()).decode()
    return cache[p]
def assets(txt): return re.sub(r"\.\./assets/[A-Za-z0-9_./-]+\.(?:webp|png|svg|woff2)", lambda m: data(m.group(0)), txt)
def links(txt):
    txt = re.sub(r'href="(texture|sound|locked)\.html', lambda m: f'href="{OUT[m.group(1)+".html"]}', txt)
    return txt.replace("${kind}.html", "${kind}-studio.html")
for src, dst in OUT.items():
    h = open(os.path.join(S, src)).read()
    h = re.sub(r'<link rel="stylesheet" href="([^"]+)">', lambda m: "<style>\n" + open(os.path.join(S, m.group(1))).read() + "\n</style>", h)
    h = re.sub(r'<script src="([^"]+)"></script>', lambda m: "<script>\n" + open(os.path.join(S, m.group(1))).read().replace("</script", "<\\/script") + "\n</script>", h)
    h = links(assets(h))
    assert "../assets" not in h and 'src="engine.js"' not in h
    open(os.path.join(D, dst), "w").write(h)
    print(dst, round(len(h) / 1024), "KB")
#!/bin/bash
# Sync the design folder to node-2 and take screenshots there (capped agents slice), then pull the PNGs back.
set -euo pipefail
D=/root/agent-notes/cyrus-designs; H=root@178.63.94.114; RD=/tank/nxeon-build/tmp/cyrus-designs
JOBS=${1:-$D/tools/jobs.json}
rsync -a --delete --exclude shots $D/ $H:$RD/
scp -q "$JOBS" $H:$RD/tools/jobs-run.json
ssh -o BatchMode=yes $H "mkdir -p $RD/shots && cd $RD/tools && systemd-run --quiet --pipe --wait --collect --slice=nxeon-build-agents.slice -p MemoryMax=2G -p CPUQuota=200% --working-directory=$RD/tools -E NODE_PATH=/tank/nxeon-build/wt/baseline-tests/node_modules -E PLAYWRIGHT_BROWSERS_PATH=/root/.cache/ms-playwright nice -n 10 timeout 300 /usr/bin/env node shot.js $RD/${SRCDIR:-src} $RD/shots $RD/tools/jobs-run.json"
rsync -a $H:$RD/shots/ $D/shots/
// Playwright screenshots of the mockups. Usage: node shot.js <srcdir> <outdir> <jobs.json>
const { chromium } = require("playwright");
const fs = require("fs"), path = require("path");
(async () => {
  const [src, out, jobsF] = process.argv.slice(2);
  const jobs = JSON.parse(fs.readFileSync(jobsF, "utf8"));
  const b = await chromium.launch({ args: ["--disable-gpu"] });
  for (const j of jobs) {
    const p = await b.newPage({ viewport: { width: j.w, height: j.h }, deviceScaleFactor: j.dpr || 1 });
    const errs = []; p.on("pageerror", (e) => errs.push(e.message)); p.on("console", (m) => { if (m.type() === "error") errs.push(m.text()); });
    await p.goto("file://" + path.join(src, j.file) + (j.q ? "?" + j.q : ""));
    await p.waitForTimeout(j.wait || 900);
    if (j.eval) { await p.evaluate(j.eval); await p.waitForTimeout(300); }
    if (j.click) for (const c of j.click) { await p.click(c); await p.waitForTimeout(400); }
    await p.screenshot({ path: path.join(out, j.out), fullPage: !!j.full });
    console.log(j.out, errs.length ? "ERRORS: " + errs.join(" | ") : "ok");
    await p.close();
  }
  await b.close();
})();
