  // ── portal chrome (dark island in both themes, exactly like the shipped studio pages) ──
  const SIDE = [["Overview", [["home", "Dashboard", 0, 1]]], ["Compute", [["deploy", "Deploy"], ["package", "My Services", "FREE"]]],
    ["Build", [["matrix", "Matrix", "AI"], ["sparkles", "Build with AI"], ["flask", "NxLabs", "MOD STORE"]]],
    ["Tools", [["arrowR", "Migration"], ["sliders2", "Tools"], ["globe", "Server Directory"]]],
    ["Network", [["route", "Domains"], ["ssl", "SSL"]]], ["Mail", [["mail", "Mailboxes"], ["inbox", "Inbox"]]], ["Account", [["gift", "Refer & earn"]]]];
  window.portalSide = () => `<aside class="pside" aria-label="Nxeon portal">
      <div class="plogo"><img src="../assets/brand/nxeon-logo.png" alt="Nxeon"></div>
      <nav class="pnav">${SIDE.map(([h, items]) => `<div class="psec">${h}</div>` + items.map(([ic, l, b, on]) => `<a class="${on ? "on" : ""}">${I(ic)}<span>${l}</span>${b ? `<i class="pb">${b}</i>` : ""}</a>`).join("")).join("")}</nav>
      <div class="pbal"><div class="psec" style="margin:0 0 6px">${I("coin")} Account balance</div><div class="pbal-r"><b>$0.00</b><a>Add funds</a></div></div>
    </aside>`;
  window.portalTop = () => `<header class="ptop">
      <label class="psearch">${I("search")}<span>Search anything...</span><i class="kbd">⌘K</i></label>
      <a class="pcyrus"><img src="../assets/brand/ymark-dark.webp" alt="">Cyrus<i>BETA</i></a>
      <span class="ptok"><img src="../assets/brand/token-coin.webp" alt=""><b>0</b><i>+</i></span>
      <span class="pcur">USD $ ${I("chevD")}</span>
      <span class="pic" data-theme-ic2>${I("moon")}</span><span class="pic" style="color:#ff4d6d">${I("bug")}</span><span class="pic">${I("sparkle")}</span><span class="pic" style="color:#c084fc">${I("bell")}</span>
      <span class="pic box">${I("diamond")}</span>
      <span class="pav"><i>S</i>studio-all</span><span class="pic">${I("logout")}</span>
    </header>`;
  // Cyrus top bar: crumbs = [[label, iconHtml, href]] after Core > Minecraft
  window.cyTop = (crumbs, right) => `<header class="topbar">
      <a class="brand" aria-label="Cyrus home"><img class="wm-d" src="../assets/brand/wordmark-dark.webp" alt="Cyrus"><img class="wm-l" src="../assets/brand/wordmark-light.webp" alt="Cyrus"><small>Mod Forge</small></a>
      <nav class="crumbs glass-soft" aria-label="Location">
        <a class="crumb"><span class="core"></span>Core</a>${I("chevR")}<a class="crumb"><img src="../assets/brand/minecraft.svg" alt="">Minecraft</a>
        ${crumbs.map((c, i) => `${I("chevR")}<a class="crumb ${i === crumbs.length - 1 ? "on" : ""}" ${c[2] ? `href="${c[2]}"` : ""} ${i === crumbs.length - 1 ? 'aria-current="page"' : ""}>${c[1] || ""}${c[0]}</a>`).join("")}
      </nav>
      <div class="tb-r">${right || ""}
        <span class="chip glass-soft hide-n" title="Cyrus tokens"><img class="coin" src="../assets/brand/token-coin.webp" alt=""><b>250</b></span>
