      </div>
    </header>`;
  window.catDot = (rgb) => `<span class="dot" style="background:rgb(${rgb});box-shadow:0 0 8px rgb(${rgb})"></span>`;
  window.mountShell = (top, body) => {
    document.getElementById("app").innerHTML = portalSide() + portalTop() + `<section class="cyrus">${top}${body}</section>`;
  };
  window.mockBar = (links, extra) => `<div class="mockctl"><span class="eyebrow">Mockup</span>${links.map(([h, l, on]) => `<a class="btn xs ${on ? "on" : ""}" href="${h}">${l}</a>`).join("")}${extra || ""}</div>`;
  window.$ = (id) => document.getElementById(id);
  window.$$ = (sel, root) => Array.from((root || document).querySelectorAll(sel));
  window.on = (root, ev, sel, fn) => root.addEventListener(ev, (e) => { const t = e.target.closest(sel); if (t && root.contains(t)) fn(e, t); });
  window.meter = (label, used, cap, opt = {}) => {
    const p = Math.min(100, (used / cap) * 100), st = used > cap ? "bad" : p >= 80 ? "warn" : "ok";
    return `<div class="meter ${st}" title="${label}: ${used} of ${cap}${opt.title ? " · " + opt.title : ""}"><div class="meter-h"><span>${label}</span><b class="mono">${used}<i>/${cap}</i></b></div><div class="meter-t"><i style="width:${Math.max(p, used ? 2 : 0)}%"></i></div></div>`;
  };
  // Minecraft text colours (named colours of the design IR)
  window.MC = { black: "#000000", dark_blue: "#0000AA", dark_green: "#00AA00", dark_aqua: "#00AAAA", dark_red: "#AA0000", dark_purple: "#AA00AA", gold: "#FFAA00", gray: "#AAAAAA", dark_gray: "#555555", blue: "#5555FF", green: "#55FF55", aqua: "#55FFFF", red: "#FF5555", light_purple: "#FF55FF", yellow: "#FFFF55", white: "#FFFFFF" };
  window.mcText = (t) => `<span class="mct" style="--mc:${MC[t.color] || t.color || "#fff"}">${esc(t.text)}</span>`;

  // ── sample pixel art (drawn for the mockups; in game the client draws the real vanilla items) ──
  // A tiny op DSL in the spirit of TextureSpec: px / line / rect / poly / disc, then one outline colour (Style DNA).
  const OUT = "#15121f";
  function grid() { return Array.from({ length: 16 }, () => Array(16).fill(null)); }
  function put(g, x, y, c) { x = Math.round(x); y = Math.round(y); if (x >= 0 && y >= 0 && x < 16 && y < 16) g[y][x] = c; }
  function line(g, x1, y1, x2, y2, c) { const n = Math.max(Math.abs(x2 - x1), Math.abs(y2 - y1)) || 1; for (let i = 0; i <= n; i++) put(g, x1 + ((x2 - x1) * i) / n, y1 + ((y2 - y1) * i) / n, c); }
  function rect(g, x, y, w, h, c) { for (let j = y; j < y + h; j++) for (let i = x; i < x + w; i++) put(g, i, j, c); }
  function inPoly(pts, x, y) { let ins = false; for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) { const [xi, yi] = pts[i], [xj, yj] = pts[j]; if ((yi > y) !== (yj > y) && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) ins = !ins; } return ins; }
  function poly(g, pts, c) { for (let y = 0; y < 16; y++) for (let x = 0; x < 16; x++) if (inPoly(pts, x + 0.5, y + 0.5)) g[y][x] = c; }
  function disc(g, cx, cy, rx, ry, c) { ry = ry || rx; for (let y = 0; y < 16; y++) for (let x = 0; x < 16; x++) { const dx = (x + 0.5 - cx) / rx, dy = (y + 0.5 - cy) / ry; if (dx * dx + dy * dy <= 1) g[y][x] = c; } }
  function outline(g, c) { const o = grid(); for (let y = 0; y < 16; y++) for (let x = 0; x < 16; x++) if (!g[y][x] && [[1, 0], [-1, 0], [0, 1], [0, -1]].some(([a, b]) => g[y + b] && g[y + b][x + a] && g[y + b][x + a] !== c)) o[y][x] = c; for (let y = 0; y < 16; y++) for (let x = 0; x < 16; x++) if (o[y][x]) g[y][x] = o[y][x]; }
  function shade(g, from, to, test) { for (let y = 0; y < 16; y++) for (let x = 0; x < 16; x++) if (g[y][x] === from && test(x, y)) g[y][x] = to; }
  const T = {
    sword(g, [l, d, gu, h]) { line(g, 13, 2, 6, 9, l); line(g, 14, 3, 7, 10, d); line(g, 13, 3, 7, 9, l); put(g, 14, 2, l); line(g, 3, 9, 7, 13, gu); line(g, 4, 9, 7, 12, gu); line(g, 5, 11, 2, 14, h); put(g, 1, 15, gu); },
    staff(g, [rod, gem, gem2]) { line(g, 3, 14, 11, 6, rod); line(g, 4, 14, 12, 6, rod); disc(g, 12.5, 4, 2.6, 2.6, gem); put(g, 12, 3, gem2); put(g, 11, 4, gem2); },
    pick(g, [l, d, h]) { line(g, 3, 14, 11, 6, h); line(g, 4, 14, 12, 6, h); line(g, 6, 3, 9, 2, l); line(g, 9, 2, 12, 3, l); line(g, 12, 3, 13, 6, d); line(g, 13, 6, 14, 9, d); line(g, 7, 4, 12, 4, l); line(g, 12, 4, 12, 8, d); },
    axe(g, [l, d, h]) { line(g, 3, 14, 11, 6, h); line(g, 4, 14, 12, 6, h); poly(g, [[8, 3], [12, 1], [15, 4], [13, 8]], l); shade(g, l, d, (x, y) => x + y > 15); },
    ingot(g, [l, m, d]) { poly(g, [[2, 9], [9, 5], [14, 7], [7, 12]], m); poly(g, [[3, 9], [9, 6], [12, 7], [7, 10]], l); line(g, 7, 12, 14, 8, d); line(g, 2, 10, 7, 12, d); },
    gem(g, [l, m, d]) { poly(g, [[8, 2], [14, 7], [8, 14], [2, 7]], m); poly(g, [[8, 3], [11, 7], [8, 8], [5, 7]], l); shade(g, m, d, (x, y) => y > 8 && x > 7); },
    shard(g, [l, m, d]) { poly(g, [[6, 14], [4, 7], [8, 2], [11, 6], [10, 14]], m); line(g, 7, 4, 6, 12, l); shade(g, m, d, (x) => x > 8); },
    cube(g, [t, lf, rt], pat) { poly(g, [[8, 1], [15, 4.5], [8, 8], [1, 4.5]], t); poly(g, [[1, 4.5], [8, 8], [8, 15.2], [1, 11.7]], lf); poly(g, [[8, 8], [15, 4.5], [15, 11.7], [8, 15.2]], rt); if (pat) pat(g); },
    disc(g, [l, m, d]) { disc(g, 8, 8.5, 5.6, 5.4, m); disc(g, 6.5, 6.8, 2, 1.6, l); shade(g, m, d, (x, y) => (x - 8) + (y - 8) > 4); },
    apple(g, [l, m, d, st, lf]) { disc(g, 8, 9.5, 5.4, 5, m); disc(g, 6, 7.8, 1.6, 1.4, l); shade(g, m, d, (x, y) => (x - 8) + (y - 9) > 4); line(g, 8, 3, 8, 5, st); rect(g, 9, 3, 2, 1, lf); },
    bread(g, [l, m, d]) { disc(g, 8, 8.5, 6.6, 3.6, m); line(g, 5, 7, 6, 6, l); line(g, 8, 7, 9, 6, l); line(g, 11, 7, 12, 6, l); shade(g, m, d, (x, y) => y > 9); },
    steak(g, [l, m, d, bone]) { disc(g, 7.5, 8.5, 5.6, 4.6, m); disc(g, 6, 7, 2, 1.4, l); shade(g, m, d, (x, y) => y > 10); rect(g, 12, 10, 3, 2, bone); },
    potato(g, [l, m, d]) { disc(g, 8, 9, 5.6, 4, m); put(g, 6, 7, l); put(g, 9, 7, l); put(g, 7, 11, d); put(g, 11, 10, d); },
    lump(g, [l, m]) { poly(g, [[3, 9], [6, 4], [11, 4], [14, 8], [11, 13], [5, 13]], m); put(g, 6, 6, l); put(g, 9, 8, l); put(g, 7, 10, l); },
    torch(g, [st, fl, fl2]) { rect(g, 7, 7, 2, 8, st); rect(g, 7, 4, 2, 3, fl); put(g, 7, 3, fl2); put(g, 8, 5, fl2); },
    lantern(g, [fr, gl]) { rect(g, 5, 5, 6, 9, fr); rect(g, 6, 7, 4, 5, gl); rect(g, 7, 2, 2, 3, fr); },
    bucket(g, [l, m, d]) { poly(g, [[3, 4], [13, 4], [12, 14], [4, 14]], m); rect(g, 4, 5, 8, 2, d); line(g, 4, 8, 4, 12, l); },
    saddle(g, [l, m, d]) { poly(g, [[2, 9], [5, 5], [11, 5], [14, 9], [12, 11], [4, 11]], m); line(g, 5, 6, 10, 6, l); rect(g, 7, 11, 2, 4, d); },
    tag(g, [m, l, s]) { poly(g, [[3, 6], [12, 6], [14, 9], [12, 12], [3, 12]], m); line(g, 4, 7, 10, 7, l); put(g, 12, 9, s); line(g, 2, 9, 0, 6, s); },
    leather(g, [l, m, d]) { poly(g, [[3, 4], [13, 3], [14, 12], [8, 14], [2, 12]], m); line(g, 4, 5, 9, 5, l); shade(g, m, d, (x, y) => y > 11); },
    string(g, [m]) { line(g, 2, 12, 5, 6, m); line(g, 5, 6, 8, 11, m); line(g, 8, 11, 11, 5, m); line(g, 11, 5, 14, 9, m); },
    bow(g, [w, s]) { line(g, 3, 13, 4, 7, w); line(g, 4, 7, 8, 3, w); line(g, 8, 3, 13, 2, w); line(g, 3, 13, 13, 2, s); },
    arrow(g, [sh, hd, fe]) { line(g, 3, 13, 12, 4, sh); poly(g, [[10, 3], [14, 2], [13, 6]], hd); line(g, 2, 12, 4, 14, fe); line(g, 3, 11, 5, 13, fe); },
    shieldi(g, [m, l, d]) { poly(g, [[3, 2], [13, 2], [13, 9], [8, 14], [3, 9]], m); rect(g, 7, 3, 2, 9, d); line(g, 4, 3, 4, 8, l); },
    helmet(g, [l, m, d]) { poly(g, [[3, 11], [3, 6], [6, 3], [10, 3], [13, 6], [13, 11], [11, 11], [11, 8], [5, 8], [5, 11]], m); line(g, 5, 4, 9, 4, l); },
    chest(g, [l, m, d]) { poly(g, [[2, 3], [6, 3], [8, 5], [10, 3], [14, 3], [14, 7], [12, 7], [12, 14], [4, 14], [4, 7], [2, 7]], m); line(g, 5, 8, 5, 13, l); shade(g, m, d, (x) => x > 10); },
    legs(g, [l, m, d]) { poly(g, [[4, 2], [12, 2], [12, 14], [9, 14], [8.5, 7], [7.5, 7], [7, 14], [4, 14]], m); line(g, 5, 3, 11, 3, l); },
    boots(g, [l, m, d]) { rect(g, 3, 6, 3, 6, m); rect(g, 10, 6, 3, 6, m); rect(g, 2, 11, 5, 2, d); rect(g, 9, 11, 5, 2, d); },
    bookI(g, [m, d, pg]) { rect(g, 3, 3, 10, 11, m); rect(g, 3, 3, 2, 11, d); rect(g, 12, 4, 1, 9, pg); },
    barrier(g, [r]) { disc(g, 8, 8, 6.4, 6.4, r); disc(g, 8, 8, 4.4, 4.4, null); line(g, 4, 4, 12, 12, r); line(g, 5, 4, 12, 11, r); },
    bottle(g, [gl, liq, ck]) { rect(g, 6, 2, 4, 2, ck); poly(g, [[6, 4], [10, 4], [10, 6], [13, 9], [12, 14], [4, 14], [3, 9], [6, 6]], gl); poly(g, [[4, 9], [12, 9], [12, 13], [4, 13]], liq); },
    banner(g, [cl, po, d]) { rect(g, 2, 1, 12, 1, po); rect(g, 4, 2, 8, 11, cl); poly(g, [[4, 13], [12, 13], [8, 15]], cl); line(g, 5, 4, 5, 11, d); },
    pane(g, [f]) { rect(g, 1, 1, 14, 1, f); rect(g, 1, 14, 14, 1, f); rect(g, 1, 1, 1, 14, f); rect(g, 14, 1, 1, 14, f); line(g, 4, 11, 7, 8, f); line(g, 9, 6, 11, 4, f); },
    paper(g, [m, d]) { poly(g, [[3, 2], [11, 2], [13, 4], [13, 14], [3, 14]], m); line(g, 5, 6, 11, 6, d); line(g, 5, 9, 11, 9, d); line(g, 5, 12, 9, 12, d); },
    compass(g, [rim, face, n]) { disc(g, 8, 8, 6.4, 6.4, rim); disc(g, 8, 8, 4.6, 4.6, face); line(g, 8, 4, 8, 8, n); put(g, 8, 9, rim); },
    dye(g, [l, m]) { disc(g, 8, 9, 4.8, 4.2, m); put(g, 7, 7, l); put(g, 9, 8, l); },
    bone(g, [m]) { line(g, 4, 12, 12, 4, m); line(g, 5, 12, 12, 5, m); rect(g, 2, 11, 3, 3, m); rect(g, 11, 2, 3, 3, m); },
    rod(g, [l, m]) { line(g, 4, 13, 12, 4, m); line(g, 5, 13, 13, 4, l); },
    potion(g, [gl, liq, ck]) { rect(g, 7, 2, 2, 3, ck); disc(g, 8, 10, 5, 4.6, gl); disc(g, 8, 10.8, 4, 3.4, liq); put(g, 6, 9, "#ffffff"); },
  };
  const brick = (g) => { for (let y = 5; y < 15; y += 3) for (let x = 1; x < 15; x++) if (g[y][x]) g[y][x] = "#5d5a63"; };
  const speck = (g) => { [[3, 6], [5, 9], [11, 7], [13, 9], [10, 11], [4, 12], [7, 3], [10, 3]].forEach(([x, y]) => g[y][x] && (g[y][x] = "#56535c")); };
  const rings = (g) => { [[8, 3], [7, 4], [9, 4], [8, 5]].forEach(([x, y]) => (g[y][x] = "#9a7b4f")); for (let y = 7; y < 15; y += 2) { if (g[y][3]) g[y][3] = "#4a3520"; if (g[y][12]) g[y][12] = "#3a2a18"; } };
  const glassP = (g) => { for (let y = 0; y < 16; y++) for (let x = 0; x < 16; x++) if (g[y][x]) { const edge = [[1, 0], [-1, 0], [0, 1], [0, -1]].some(([a, b]) => !(g[y + b] && g[y + b][x + a])); if (!edge && !((x + y) % 7 === 0)) g[y][x] = "rgba(200,235,255,.18)"; } };
  const SH = {
    void_reaper: ["sword", ["#d7b8ff", "#8c5cf0", "#3a2a5c", "#5a3a2a"], "#5b2bb5"],
    netherite_sword: ["sword", ["#6d6470", "#45404a", "#2b2730", "#3a2a1c"]],
    iron_sword: ["sword", ["#f2f2f2", "#b9b9bf", "#7a5a3a", "#5a3e24"]],
    storm_staff: ["staff", ["#8a6a45", "#7fd8ff", "#e9fbff"]],
    vigor_tonic: ["potion", ["#d9e6f2", "#e23d5a", "#8a6a45"]],
    potion: ["potion", ["#d9e6f2", "#7c5cff", "#8a6a45"]],
    iron_pickaxe: ["pick", ["#f2f2f2", "#a9a9b1", "#7a5a3a"]], iron_axe: ["axe", ["#e9e9ee", "#a0a0a8", "#7a5a3a"]],
    iron_ingot: ["ingot", ["#ffffff", "#d0d0d6", "#8d8d96"]], gold_ingot: ["ingot", ["#fff6a8", "#f3cb3a", "#b8860b"]],
    diamond: ["gem", ["#d9fffb", "#4fe0d2", "#1f9e93"]], emerald: ["gem", ["#c9ffd6", "#2fcf62", "#138a3c"]],
    echo_shard: ["shard", ["#9ff3ff", "#1d6f80", "#0e3e4a"]], amethyst_shard: ["shard", ["#f2d6ff", "#a970e6", "#6c3fb0"]], guild_charm: ["shard", ["#ffd6f6", "#e65cc8", "#9a2f86"]],
    cobblestone: ["cube", ["#a3a0a8", "#86838b", "#6b6870"], speck], stone_bricks: ["cube", ["#9d9aa2", "#85828a", "#6d6a72"], brick],
    oak_log: ["cube", ["#c79d63", "#6b4a2b", "#553a20"], rings], glass: ["cube", ["#d8f3ff", "#bfe6f7", "#a6d3e8"], glassP], white_wool: ["cube", ["#ffffff", "#e3e3ea", "#c9c9d2"]],
    bread: ["bread", ["#f2c27a", "#c98a3c", "#97612a"]], cooked_beef: ["steak", ["#b9774d", "#7d4a2b", "#5a321b", "#efe6d2"]], baked_potato: ["potato", ["#f6d58c", "#d4a24e", "#9c6f2c"]],
    apple: ["apple", ["#ff9a9a", "#e2312d", "#a3171a", "#6b4a2b", "#3fae49"]], golden_apple: ["apple", ["#fff7b8", "#f5c93a", "#c29012", "#6b4a2b", "#3fae49"]],
    coal: ["lump", ["#5a5560", "#25222b"]], torch: ["torch", ["#8a6a45", "#ffd36a", "#fff3c0"]], lantern: ["lantern", ["#4b4f5c", "#ffcf6a"]],
    bucket: ["bucket", ["#ffffff", "#c8c8d0", "#7f7f88"]], saddle: ["saddle", ["#c48a55", "#8a5a33", "#4f4f58"]], name_tag: ["tag", ["#e9e0c9", "#ffffff", "#8a8a92"]],
    leather: ["leather", ["#d38b55", "#a7612f", "#7a4420"]], string: ["string", ["#f4f4f4"]], bow: ["bow", ["#9a6b3c", "#e8e8e8"]], arrow: ["arrow", ["#8a6a45", "#cfd2d8", "#f2f2f2"]],
    shield: ["shieldi", ["#a37a4b", "#c9a06e", "#7c7c84"]], iron_helmet: ["helmet", ["#ffffff", "#c7c7cf", "#8d8d96"]], iron_chestplate: ["chest", ["#ffffff", "#c7c7cf", "#9a9aa3"]],
    iron_leggings: ["legs", ["#ffffff", "#c2c2ca", "#8d8d96"]], iron_boots: ["boots", ["#ffffff", "#c2c2ca", "#8d8d96"]],
    book: ["bookI", ["#9b5d3a", "#6e3d22", "#f2ead6"]], writable_book: ["bookI", ["#7a5ad0", "#4b3699", "#f2ead6"]], barrier: ["barrier", ["#e5384a"]],
    experience_bottle: ["bottle", ["#cfe8ff", "#7cf06a", "#8a6a45"]], white_banner: ["banner", ["#f4f4f4", "#8a6a45", "#cfcfd6"]], gray_stained_glass_pane: ["pane", ["#5f5c66"]],
    paper: ["paper", ["#f5f1e6", "#c9c2ae"]], guild_badge: ["paper", ["#f7e3a8", "#c9a24e"]], compass: ["compass", ["#9a9aa3", "#e9e9ee", "#e5384a"]], lime_dye: ["dye", ["#b9ff7a", "#62d22b"]],
    bone: ["bone", ["#efe9d6"]], blaze_rod: ["rod", ["#fff1a0", "#f0a21a"]], snowball: ["disc", ["#ffffff", "#e6f2ff", "#b9d2ea"]], ice: ["cube", ["#c9e4ff", "#9cc7f2", "#7aa9db"]],
    spruce_log: ["cube", ["#8a6a45", "#4a3520", "#3a2a18"], rings], snow_block: ["cube", ["#ffffff", "#e9f1fb", "#cfdbea"]], blue_ice: ["cube", ["#a9d6ff", "#76b4f0", "#5a93d6"]],
    chest: ["cube", ["#c08a4a", "#9a6a35", "#7a5226"]], glowstone: ["cube", ["#ffe9a0", "#e9c35a", "#c79a3a"]], deepslate: ["cube", ["#5b5b66", "#47474f", "#36363d"], speck], packed_ice: ["cube", ["#b9d9ff", "#8fbbea", "#7aa3d4"]],
  };
  const cache = {};
  window.iconURL = (id) => {
    id = String(id || "").replace(/^minecraft:/, "").replace(/^nx_[a-z0-9]+:/, "");
    if (cache[id]) return cache[id];
    const s = SH[id] || ["cube", ["#8a86a0", "#6e6a84", "#57536b"]];
    const g = grid(); T[s[0]](g, s[1], s[2]); if (s[0] !== "pane") outline(g, OUT);
    const cv = document.createElement("canvas"); cv.width = 16; cv.height = 16; const c = cv.getContext("2d");
    for (let y = 0; y < 16; y++) for (let x = 0; x < 16; x++) if (g[y][x]) { c.fillStyle = g[y][x]; c.fillRect(x, y, 1, 1); }
    return (cache[id] = cv.toDataURL());
  };
  window.icon = (id, size, cls) => `<img class="pxi ${cls || ""}" src="${iconURL(id)}" width="${size || 32}" height="${size || 32}" alt="">`;
  window.SAMPLE_NOTE = "Sample pixel icons drawn for this mockup. In game, the player's client draws the real item.";
})();

