/* Cyrus v2 mockups: the shipped shell (portal sidebar + portal top bar, as in impl-shots/texture-*.png) + the shared
   pieces of the five new screens. Tokens come from kit.css (= the approved v1 kit, copied from studio.css). */
.app { display: grid; grid-template-columns: 248px 1fr; grid-template-rows: 72px 1fr; height: 100vh; background: #00071a; }
.pside { grid-row: 1 / 3; background: #00071a; border-right: 1px solid rgb(120 140 255 / .09); display: flex; flex-direction: column; padding: 20px 12px 12px; min-height: 0; color: #c9d1ee; }
.plogo { padding: 4px 8px 6px; } .plogo img { height: 25px; display: block; }
.pnav { flex: 1; overflow: hidden; margin-top: 8px; }
.psec { display: flex; align-items: center; gap: 8px; font: 600 10px/1 var(--sans); letter-spacing: .2em; text-transform: uppercase; color: #8a93bd; margin: 22px 12px 8px; }
.pnav a { display: flex; align-items: center; gap: 12px; height: 39px; padding: 0 12px; border-radius: 10px; font-size: 14.5px; font-weight: 500; color: #c9d1ee; }
.pnav a svg { font-size: 19px; color: #5b8cff; }
.pnav a.on { color: #fff; background: linear-gradient(90deg, rgb(59 107 232 / .2), rgb(59 107 232 / .03)); }
.pb { margin-left: auto; font: 600 9px/1 var(--mono); letter-spacing: .08em; padding: 4px 6px; border-radius: 5px; background: rgb(255 255 255 / .07); color: #d5dbf3; font-style: normal; }
.pbal { margin-top: 8px; border: 1px solid rgb(120 140 255 / .18); border-radius: 12px; padding: 12px 14px; background: rgb(14 24 54 / .5); }
.pbal-r { display: flex; align-items: baseline; justify-content: space-between; } .pbal-r b { font: 600 22px/1 var(--display); color: #fff; } .pbal-r a { font-size: 12px; color: #9fb4ff; font-weight: 600; }
.ptop { grid-column: 2; display: flex; align-items: center; gap: 14px; padding: 0 22px 0 24px; background: #00071a; border-bottom: 1px solid rgb(120 140 255 / .07); min-width: 0; }
.psearch { display: flex; align-items: center; gap: 12px; width: 332px; height: 40px; padding: 0 10px 0 14px; border-radius: 12px; border: 1px solid rgb(120 140 255 / .2); background: rgb(16 30 56 / .55); color: #7f8db5; font-size: 13.5px; }
.psearch svg { font-size: 19px; } .psearch span { flex: 1; } .psearch .kbd { color: #8a96bd; border-color: rgb(120 140 255 / .25); }
:root[data-theme="light"] .psearch { background: #e4e9f2; border-color: #d3dae8; color: #5c6b8a; }
.pcyrus { display: inline-flex; align-items: center; gap: 9px; height: 40px; padding: 0 16px 0 18px; border-radius: 20px; color: #fff; font: 600 14px/1 var(--sans); background: linear-gradient(95deg, #5a7bff, #8b5cf6 55%, #a855f7); box-shadow: 0 6px 24px -8px rgb(124 92 255 / .9); }
.pcyrus img { width: 20px; } .pcyrus i { font: 700 9px/1 var(--mono); letter-spacing: .12em; padding: 4px 7px; border-radius: 6px; background: rgb(255 255 255 / .2); font-style: normal; }
.ptok { display: inline-flex; align-items: center; gap: 8px; color: #fff; font: 600 13px/1 var(--mono); } .ptok img { width: 19px; } .ptok i { display: grid; place-items: center; width: 22px; height: 22px; border-radius: 6px; background: #7c5cff; font-style: normal; }
.pcur { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 10px; border-radius: 8px; border: 1px solid rgb(120 140 255 / .2); font-size: 12.5px; color: #dfe5fb; }
.pic { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 10px; color: #9aa6ff; font-size: 21px; }
.pic.box { border: 1px solid rgb(160 140 255 / .35); background: rgb(124 92 255 / .12); color: #e3dcff; }
.pav { display: inline-flex; align-items: center; gap: 10px; font-weight: 600; font-size: 13.5px; color: #fff; margin-left: 6px; } .pav i { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%; background: #6d5cff; font-style: normal; }
.ptop .pav { margin-left: auto; }
.cyrus { grid-column: 2; grid-row: 2; border-top-left-radius: 0; }
