.btn.on { color: var(--accent-ink); border-color: var(--accent-line); background: var(--accent-soft); }

/* meters (caps shown as budgets) */
.meters { display: grid; gap: 8px 14px; }
.meter-h { display: flex; justify-content: space-between; align-items: baseline; font-size: 11px; color: var(--muted); gap: 6px; white-space: nowrap; }
.meter-h b { font-size: 11px; color: var(--ink); font-weight: 500; } .meter-h b i { font-style: normal; color: var(--faint); }
