.note.bad { border-color: color-mix(in srgb, var(--bad) 35%, transparent); background: var(--bad-soft); } .note.bad > svg { color: var(--bad); }
.note b { color: var(--ink); font-weight: 600; }
.banner { display: flex; align-items: center; gap: 10px; padding: 9px 12px; border-radius: var(--r-md); border: 1px solid color-mix(in srgb, var(--warn) 40%, transparent); background: var(--warn-soft); font-size: 12px; color: var(--ink-2); }
.banner > svg { color: var(--warn); font-size: 16px; } .banner b { color: var(--ink); }

