  .n-act { display: flex; gap: 8px; padding: 12px 14px 14px; border-top: 1px solid var(--line); } .n-act .btn { flex: 1; height: 38px; }
  .n-sec { padding: 12px 14px; border-top: 1px solid var(--line); }
  .n-sec .eyebrow { display: block; margin-bottom: 8px; }
